insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-000000000036', 'en', null, 'Software Engineering', 'Software engineering is the disciplined practice of building, operating, and maintaining software systems that people can depend on over time. This course moves from what software engineering really is, through the development life cycle, requirements, design, version control, testing, and quality, to maintenance, deployment, and professional ethics. Its structure is adapted from the Software engineering article on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 41, true, 'technology', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000036', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Software engineering differs from programming mainly because it...","options":["is only about writing faster code","applies a disciplined, systematic process to building and maintaining whole systems","avoids using any process models","means coding without requirements"],"answer":1,"explanation":"Programming writes working code; engineering builds and sustains an entire system over its life - see ''What software engineering is''."},{"prompt":"In the waterfall model, the phases are...","options":["repeated every day","carried out in a fixed sequence, each finishing before the next begins","skipped entirely","chosen at random"],"answer":1,"explanation":"Waterfall runs the life cycle once, in strict order, with no overlap."},{"prompt":"Agile methods emphasize...","options":["one huge release at the very end","short iterations with frequent feedback and working software","no communication with customers","fixed plans that never change"],"answer":1,"explanation":"Agile delivers small increments quickly and values responding to change."},{"prompt":"Requirements engineering is the practice of...","options":["writing code first and asking later","discovering, documenting, and agreeing on what the system must do","deleting old features","choosing a programming language"],"answer":1,"explanation":"It is the cheapest place to prevent expensive misunderstandings."},{"prompt":"Two modules are loosely coupled when...","options":["each depends heavily on the internals of the other","they share all of their variables","a change in one rarely forces a change in the other","they are written by the same person"],"answer":2,"explanation":"Low coupling keeps a change local instead of rippling everywhere."},{"prompt":"A unit test checks...","options":["the entire deployed system at once","a single small piece of code in isolation","only the interface colors","the speed of the network"],"answer":1,"explanation":"Unit tests are small, fast, and pinpoint failures precisely."},{"prompt":"Git is best described as...","options":["a text editor","a distributed version control system for tracking changes","a database server","a deployment cloud"],"answer":1,"explanation":"Git records every change and gives each developer a full copy of the history."},{"prompt":"Technical debt refers to...","options":["money owed to a hosting company","the future cost of quick shortcuts taken in code and design","the price of a compiler","unpaid developer salaries"],"answer":1,"explanation":"Shortcuts taken now are repaid later as slower, riskier change."}]}'::jsonb, null, 10),
  (2, 'What software engineering is, and why it matters', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Say clearly how software engineering differs from plain programming, name the forces that make it necessary, and explain why it matters for cost and reliability. Warm-up: from the diagnostic, which single word best captures what separates engineering from coding - speed, or process?"},{"heading":"The idea","text":"Software engineering is the systematic, disciplined approach to the development, operation, and maintenance of software. Programming is the act of writing code that works today. Software engineering is the larger job of building a system that keeps working next year, while many people change it, and while the world around it shifts. A one-time script you run on your own laptop can be rough; a payroll system that thousands of companies trust cannot. The difference is not cleverness but durability and scale. Most of a system''s total cost does not arrive when it is first written; it arrives later, during maintenance, as defects are fixed and features are added. Because of that, engineers optimize for code that is readable, testable, and safe to change, not merely code that runs once. They manage three forces that small programs can ignore: growing complexity, constant change, and collaboration among many hands. The goal is a system that stays trustworthy as it grows."},{"heading":"Key practices & examples","text":"In practice software engineering shows up as a set of shared habits. Teams keep every change in version control so history is never lost. They write automated tests so a change in one place cannot silently break another. They review each other''s code before it merges, track work in an issue system, and record decisions in design notes. Consider two programs. A weekend weather script might be fifty lines with no tests; if it breaks, you simply rerun it. A hospital scheduling platform is different: a wrong change could cancel real appointments, so it needs requirements, tests, reviews, and a safe release process. The same instruction - update a record - carries tiny risk in one case and serious risk in the other. Pseudocode for a guarded change might read:\n\n  if tests_pass(change) and review_approved(change):\n      merge(change)\n  else:\n      send_back(change)\n\nThe point is that engineering wraps raw coding in checks that make change survivable."},{"heading":"Your turn","text":"1) In one sentence, how does software engineering differ from programming? 2) Where does most of a system''s cost appear? 3) Name two habits that make change safer. 4) Why does a throwaway script need less process than a banking system? 5) Which three forces does engineering manage that small programs can ignore? Answers: 1) Programming writes working code; engineering builds and sustains a whole system over time, among many people. 2) In maintenance, after the first release. 3) Any two of: version control, automated tests, code review, issue tracking, design notes. 4) The script is low risk and short lived, so a mistake is cheap and easy to redo. 5) Complexity, change, and collaboration."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing that writing more code faster is the whole goal - unreadable code that no one can safely change costs far more later. Mistake: treating the first working version as the finish line, when maintenance is the longest and most expensive phase. Exit: (a) True or false: most software cost comes before the first release. (b) Name one practice that helps a team change code without fear. Answers: (a) False - most cost comes during maintenance after release. (b) Any of: automated testing, code review, version control, or clear documentation."}]}'::jsonb, 'Programming is one activity inside software engineering; the larger job is keeping a whole system correct and changeable over years.', 13),
  (3, 'The life cycle and process models', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main phases of the software development life cycle and compare how waterfall, iterative, and agile models arrange them. Warm-up: if you cannot know every requirement up front, is it wiser to plan everything once or to work in short cycles?"},{"heading":"The idea","text":"The software development life cycle, or SDLC, is the set of activities a system passes through from idea to retirement: requirements, design, implementation, testing, deployment, and maintenance. A process model decides how those activities are ordered in time. The waterfall model runs them once, in strict sequence, each phase finishing before the next starts; it is simple and easy to audit, but it assumes the requirements are known early and rarely change. Iterative models repeat the cycle in chunks, building and refining the system in successive passes so that lessons from one pass improve the next. Agile models take this further: they work in short iterations, often one to four weeks, delivering small increments of working software and inviting feedback continuously. Agile values responding to change over following a fixed plan. No model is best everywhere; the right choice depends on how stable the requirements are and how costly a late mistake would be."},{"heading":"Key practices & examples","text":"Picture building a reporting tool. Under waterfall, you would gather every requirement, write a full design, build it all, then test, then release - months later. If a key report was misunderstood at the start, you discover it at the end, when fixing it is expensive. Under an agile approach, you would ship a single working report in two weeks, show it to users, learn what they actually need, and adjust in the next iteration. A typical agile rhythm looks like:\n\n  for each sprint in project:\n      pick highest_value_items\n      build and test them\n      demo to users\n      collect feedback\n\nSpiral and incremental models sit between these poles, adding explicit risk reviews or staged deliveries. Many real teams blend ideas: a stable, regulated component may use a waterfall-like gate, while a fast-moving feature uses short iterations. The practical skill is matching the model to the uncertainty: high uncertainty rewards short cycles and frequent feedback; low uncertainty and heavy audit needs may reward sequential planning."},{"heading":"Your turn","text":"1) List the main SDLC phases in order. 2) What assumption does waterfall make about requirements? 3) How long is a typical agile iteration? 4) Why do short cycles help when requirements are uncertain? 5) Name one situation where a sequential model is reasonable. Answers: 1) Requirements, design, implementation, testing, deployment, maintenance. 2) That they are known early and will not change much. 3) Roughly one to four weeks. 4) Each cycle delivers something real, so misunderstandings surface early and cheaply. 5) A stable, heavily regulated system where every change must be audited and requirements are fixed."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating agile as an excuse to skip planning and documentation - agile reorders and lightens them, it does not delete them. Mistake: forcing waterfall onto a project whose requirements are still unknown, which hides problems until the very end. Exit: (a) Which model repeats the cycle in short, feedback-driven passes? (b) In waterfall, can a later phase begin before the previous one finishes? Answers: (a) Agile, an iterative family of models. (b) No - each phase completes before the next begins."}]}'::jsonb, 'A process model is a plan for ordering the work; the same activities appear in each one, only arranged differently.', 13),
  (4, 'Requirements engineering', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what requirements engineering is, tell functional from non-functional requirements, and describe how to gather and validate them. Warm-up: ''the site should be fast'' - is that a clear requirement you could actually test?"},{"heading":"The idea","text":"Requirements engineering is the disciplined work of discovering, documenting, and agreeing on what a system must do, before and while it is built. It is widely the cheapest place to prevent expensive mistakes, because a misunderstanding caught in a conversation costs far less than one caught after release. Requirements come in two broad kinds. Functional requirements say what the system must do: a user can reset a password, an invoice can be exported. Non-functional requirements say how well it must do it: respond within two seconds, stay available 99.9 percent of the time, protect stored data. A good requirement is specific, testable, and free of hidden assumptions. ''The site should be fast'' is not testable; ''each page loads in under two seconds for 95 percent of users'' is. Requirements are gathered from stakeholders through interviews, observation, and prototypes, then written down, prioritized, and checked for conflicts. Because needs change, requirements are revisited throughout the project rather than frozen on day one."},{"heading":"Key practices & examples","text":"Suppose a client asks for ''a secure login.'' That single phrase hides several real requirements. Good practice turns it into concrete, checkable statements, for example:\n\n  - A user signs in with email and password. (functional)\n  - After five failed attempts, the account locks for ten minutes. (functional)\n  - Passwords are stored only as salted hashes. (non-functional, security)\n  - The sign-in page responds within one second. (non-functional, performance)\n\nEach line can be tested and argued about on its own. Teams often capture requirements as user stories in the form ''As a role, I want a goal, so that a benefit,'' paired with acceptance criteria that define done. Prioritization matters because time is limited; a common scheme ranks items as must have, should have, could have, and will not have this time. Validation closes the loop: show a prototype or demo and ask stakeholders whether it truly matches the need, correcting the written requirements when it does not."},{"heading":"Your turn","text":"1) Define requirements engineering in one sentence. 2) Classify ''the report exports to a spreadsheet'' - functional or non-functional? 3) Classify ''the system handles 1000 users at once'' - which kind? 4) Rewrite ''the app should be reliable'' as a testable requirement. 5) Why are requirements revisited rather than frozen? Answers: 1) The work of discovering, documenting, and agreeing on what a system must do. 2) Functional. 3) Non-functional, a performance or scalability requirement. 4) For example, ''the app is available at least 99.9 percent of each month.'' 5) Because real needs change and new understanding appears as the work proceeds."},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing vague requirements like ''fast'' or ''user friendly'' that no one can test or agree on. Mistake: describing a solution instead of a need, which quietly removes better options. Exit: (a) Give the two broad categories of requirements. (b) What makes a requirement testable? Answers: (a) Functional and non-functional. (b) It is specific and measurable, so you can clearly decide whether the finished system meets it."}]}'::jsonb, 'A good requirement says what the system must do or how well it must do it, not how it is coded.', 12),
  (5, 'Design principles and architecture patterns', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply core design principles - modularity, abstraction, coupling and cohesion, and the SOLID guidelines - and recognize a few common architecture patterns. Warm-up: if changing one feature forces edits in ten unrelated files, what is probably wrong with the design?"},{"heading":"The idea","text":"Software design is how you divide a system into parts and decide how those parts fit together. Modularity breaks a system into units with clear responsibilities, so each can be understood and changed on its own. Abstraction hides the messy details of a unit behind a simple interface, letting callers depend on what it does, not how. Two measures judge the result. Coupling is how strongly modules depend on one another; low coupling is better, because a change in one part does not ripple everywhere. Cohesion is how focused a single module is; high cohesion is better, because everything inside a module serves one purpose. The SOLID guidelines sharpen this for object-oriented code: Single responsibility (one reason to change per class), Open-closed (open to extension, closed to modification), Liskov substitution (subtypes behave like their base type), Interface segregation (many small interfaces beat one fat one), and Dependency inversion (depend on abstractions, not concrete details). Together these principles aim at one goal: making change safe and local."},{"heading":"Key practices & examples","text":"Imagine an order system that mixes pricing, tax, and email sending in one giant class. Any change risks the others - low cohesion and high coupling. Splitting it respects single responsibility:\n\n  class Pricing:   def total(cart) ...\n  class TaxRules:  def tax(total, region) ...\n  class Mailer:    def send(receipt) ...\n\nNow a tax change touches only TaxRules. Dependency inversion lets the checkout depend on an abstract Mailer interface, so a test can swap in a fake that records messages instead of sending real ones. At a larger scale, architecture patterns organize whole systems. Layered architecture stacks presentation, business logic, and data access. Model-view-controller separates data, display, and input handling. Client-server splits a shared back end from many front ends. Microservices break a system into small, independently deployable services, trading simplicity for flexibility. Event-driven designs react to messages on a queue. Each pattern is a reusable answer to a recurring structural problem; the skill is choosing one whose trade-offs fit your constraints rather than following fashion."},{"heading":"Your turn","text":"1) Define coupling and say whether high or low is better. 2) Define cohesion and say whether high or low is better. 3) What does the single responsibility principle require of a class? 4) Which SOLID letter says ''depend on abstractions, not concrete details''? 5) Name one architecture pattern and the problem it addresses. Answers: 1) How strongly modules depend on each other; low is better. 2) How focused a module is on one purpose; high is better. 3) That it has only one reason to change. 4) Dependency inversion, the D. 5) For example, layered architecture separates presentation, logic, and data; microservices let parts deploy independently."},{"heading":"Common mistakes & exit ticket","text":"Mistake: chasing clever structure the system does not need, which adds complexity without benefit. Mistake: confusing coupling and cohesion - you want them pulling opposite ways, low coupling but high cohesion. Exit: (a) What are the five SOLID principles, by name? (b) Why is low coupling valuable? Answers: (a) Single responsibility, open-closed, Liskov substitution, interface segregation, dependency inversion. (b) Because a change in one module is less likely to force changes across the rest of the system."}]}'::jsonb, 'Low coupling and high cohesion are two sides of good structure: parts that mind their own business and connect through thin, clear seams.', 14),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Compared with programming, software engineering is best described as...","options":["writing code as fast as possible","a systematic approach to building and maintaining whole systems","avoiding all documentation","coding without any tests"],"answer":1,"explanation":"Engineering adds disciplined process around raw coding so a system lasts."},{"prompt":"Which model delivers small increments in short, feedback-driven iterations?","options":["waterfall","agile","a single big-bang release","no model at all"],"answer":1,"explanation":"Agile works in short cycles and invites feedback continuously."},{"prompt":"''The page must load in under two seconds'' is which kind of requirement?","options":["functional","non-functional","a user story title","a test name"],"answer":1,"explanation":"It states how well the system performs, not a new behavior."},{"prompt":"Low coupling between modules means...","options":["they share all of their data","a change in one rarely forces a change in another","they must live in one file","they cannot be tested"],"answer":1,"explanation":"Low coupling keeps changes local and the system easier to modify."},{"prompt":"The ''S'' in SOLID stands for...","options":["scalability","single responsibility","security","sequence"],"answer":1,"explanation":"A class should have a single responsibility, so one reason to change."},{"prompt":"A good requirement is...","options":["vague so it stays flexible","specific and testable","a description of the code","never written down"],"answer":1,"explanation":"You must be able to decide clearly whether the system meets it."}]}'::jsonb, null, 8),
  (7, 'Version control and collaboration with Git', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why version control matters, describe the basic Git workflow, and compare a couple of common branching strategies. Warm-up: before version control, how did a team know who changed what, and how could they undo a bad edit?"},{"heading":"The idea","text":"Version control is a system that records every change to a project over time, so you can see history, compare versions, and return to any earlier state. Git is the most widely used version control system. It is distributed, meaning every developer has a full copy of the history, so work can continue offline and no single machine is the sole source of truth. The core unit is the commit: a snapshot of the project plus a message explaining why the change was made. Commits form a history you can read like a logbook. A branch is a separate line of development, letting you build a feature without disturbing the stable main line; when the feature is ready, you merge it back. Version control is also the backbone of collaboration. Many people can work at once, each on their own branch, and the tool helps combine their work and flag conflicts where two people changed the same lines. Good messages and small, focused commits make that history genuinely useful."},{"heading":"Key practices & examples","text":"A typical daily flow with Git looks like this:\n\n  git checkout -b add-search      # start a feature branch\n  # edit files\n  git add .\n  git commit -m \"Add search box to header\"\n  git push origin add-search      # share the branch\n\nYou then open a pull request so teammates can review the change before it joins the main branch. Teams adopt a branching strategy to keep this orderly. In a feature-branch workflow, every change starts on its own short-lived branch and merges through review. Trunk-based development keeps branches very short and integrates into the main line often, reducing painful merges. Gitflow adds dedicated branches for releases and hotfixes, which suits scheduled releases but adds overhead. When two branches edit the same lines, Git reports a merge conflict; a human decides how to combine them, then commits the resolution. The habits that matter most are small commits, clear messages, frequent integration, and never rewriting shared history that others depend on."},{"heading":"Your turn","text":"1) What is a commit? 2) What is a branch for? 3) Why is Git called distributed? 4) What is a pull request used for? 5) Name one branching strategy and one of its trade-offs. Answers: 1) A saved snapshot of the project with a message explaining the change. 2) To develop work in parallel without disturbing the stable main line. 3) Because every developer has a full copy of the history, not just a central server. 4) To propose a change and let teammates review it before it merges. 5) For example, Gitflow supports scheduled releases but adds extra branches and overhead; trunk-based development reduces merge pain but needs frequent integration."},{"heading":"Common mistakes & exit ticket","text":"Mistake: giving commits empty or meaningless messages, which turns the history into noise. Mistake: letting a branch live for weeks, so merging it becomes a large, conflict-filled ordeal. Exit: (a) What does a merge conflict mean? (b) Why keep commits small and frequent? Answers: (a) Two changes edited the same lines, so a person must decide how to combine them. (b) Small, frequent commits are easier to review, understand, and undo, and they cause fewer large conflicts."}]}'::jsonb, 'A commit is a saved snapshot with a message; a branch is a movable line of commits you can develop in parallel.', 13),
  (8, 'Testing, reviews, and refactoring', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish unit, integration, and system testing, explain test-driven development, and describe how reviews and refactoring protect code quality. Warm-up: if a test only runs after you ship, what has it really protected?"},{"heading":"The idea","text":"Testing is how engineers gain confidence that software behaves as intended. It comes in layers. A unit test checks one small piece - a single function or class - in isolation, running fast and pinpointing failures precisely. An integration test checks that pieces work together, for example that a service correctly reads from a database. A system test exercises the whole application end to end, as a user would. The layers complement each other: many quick unit tests catch small errors, while fewer integration and system tests catch problems that only appear when parts combine. Test-driven development, or TDD, reverses the usual order: you write a failing test that states what the code should do, write just enough code to pass it, then clean up. This keeps code testable by design and documents intent. Automated tests are run on every change so a regression - a feature that used to work and now does not - is caught immediately rather than by a user. Quality is not a final inspection; it is built in continuously."},{"heading":"Key practices & examples","text":"A unit test is small and direct:\n\n  def test_add():\n      assert add(2, 3) == 5\n\nThe TDD rhythm is red, green, refactor: write a failing test (red), make it pass with the simplest code (green), then improve the structure while the test keeps you honest. Beyond tests, two practices guard quality. Code review means a teammate reads a change before it merges, catching bugs, unclear names, and risky designs, while spreading knowledge across the team. Good reviews are specific and kind, and they focus on the change, not the person. Refactoring means improving the internal structure of code without changing what it does from the outside - renaming for clarity, splitting a long function, removing duplication. Because the behavior is unchanged, a solid test suite makes refactoring safe: you restructure freely and rerun the tests to confirm nothing broke. Together, tests, reviews, and refactoring form a loop that keeps a growing codebase understandable instead of letting it rot into a tangle no one dares touch."},{"heading":"Your turn","text":"1) What does a unit test check? 2) What does an integration test add that unit tests miss? 3) State the three steps of the TDD cycle. 4) What is refactoring? 5) Name one benefit of code review besides catching bugs. Answers: 1) One small piece of code, such as a single function, in isolation. 2) That separate pieces work correctly when combined. 3) Red (write a failing test), green (make it pass), refactor (improve the code). 4) Improving the internal structure of code without changing its external behavior. 5) It spreads knowledge across the team, and also improves clarity and design."},{"heading":"Common mistakes & exit ticket","text":"Mistake: testing only by hand at the end, so regressions slip through and every release is tense. Mistake: refactoring without a safety net of tests, so you cannot tell whether you changed behavior by accident. Exit: (a) Which test layer exercises the whole application end to end? (b) Why does a good test suite make refactoring safe? Answers: (a) System testing. (b) After each structural change you rerun the tests, which confirm the external behavior is unchanged."}]}'::jsonb, 'Unit tests check pieces, integration tests check how pieces fit, system tests check the whole; test-driven development writes the test before the code.', 14),
  (9, 'Key terms', 'vocab', '{"items":[{"term":"software engineering","translation":"the systematic, disciplined approach to building, operating, and maintaining software over its whole life","example":"Software engineering adds process, tests, and review around raw coding so change stays safe."},{"term":"software development life cycle (SDLC)","translation":"the activities a system passes through from idea to retirement: requirements, design, implementation, testing, deployment, maintenance","example":"The team tracked each feature through the full SDLC."},{"term":"requirement","translation":"a statement of what a system must do (functional) or how well it must do it (non-functional)","example":"''Pages load in under two seconds'' is a non-functional requirement."},{"term":"coupling","translation":"how strongly one module depends on another; lower is better","example":"Loose coupling let them replace the payment module without touching checkout."},{"term":"cohesion","translation":"how focused a single module is on one purpose; higher is better","example":"A class with high cohesion does one job and does it well."},{"term":"refactoring","translation":"improving the internal structure of code without changing its external behavior","example":"Refactoring split the long function into three readable ones."},{"term":"technical debt","translation":"the future cost created by quick shortcuts in code or design that must later be repaid","example":"Skipping tests to hit a deadline added technical debt."},{"term":"continuous integration","translation":"the practice of merging and automatically testing changes frequently, often many times a day","example":"Continuous integration ran the full test suite on every commit."}]}'::jsonb, null, 10),
  (10, 'Maintenance, deployment, and professional ethics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why maintenance dominates a system''s cost, describe technical debt and documentation, and outline deployment, continuous integration and delivery, and professional ethics. Warm-up: once software is released, is the engineering effort mostly over or mostly beginning?"},{"heading":"The idea","text":"Most of a system''s life is spent in maintenance - fixing defects, adapting to new environments, and adding features long after the first release. Maintenance is usually the largest share of total cost, which is why engineers prize code that is easy to read and change. Technical debt is a useful metaphor for the shortcuts that make maintenance harder: a quick, messy fix is like borrowing time now and paying interest later, as every future change takes longer. Debt is sometimes a reasonable choice, but it must be tracked and repaid, or it compounds until the system is nearly frozen. Documentation keeps knowledge alive beyond the people who wrote the code: a short, honest explanation of why a design exists is worth more than a pile of obvious comments. Deployment is the act of getting a tested version safely into the hands of users. Done carelessly it is risky; done well, it is routine and reversible, so a bad release can be rolled back quickly."},{"heading":"Key practices & examples","text":"Continuous integration and continuous delivery, together called CI/CD, automate the path from a committed change to a running system. A pipeline might read:\n\n  on every push:\n      run the tests\n      build the application\n      if all green: deploy to staging\n      await approval, then release to users\n\nBecause each step is automated and repeatable, releases become small, frequent, and low drama, and a failing test stops a bad change before it reaches users. Small releases also make it easy to find and undo whatever caused a problem. Alongside these technical habits sits professional ethics, which is not optional. Engineers build systems that affect real people, so they are responsible for honesty about what software can and cannot do, for protecting user privacy and data, for reporting serious risks rather than hiding them, and for not shipping work they know to be unsafe. Professional codes, such as the joint software engineering code of ethics, state that the public interest comes first. Competence, honesty, and care for those affected are part of the job, not an afterthought."},{"heading":"Your turn","text":"1) Which phase usually consumes the largest share of a system''s cost? 2) Explain technical debt in your own words. 3) What does CI/CD automate? 4) Why do small, frequent releases reduce risk? 5) Name two ethical duties of a software engineer. Answers: 1) Maintenance, after the first release. 2) The future cost of shortcuts in code or design, which makes later changes slower until the debt is repaid. 3) The path from a committed change through testing and building to deployment. 4) Each release carries less change, so problems are easier to spot and to roll back. 5) Any two of: protect user privacy and data, be honest about capabilities and risks, put the public interest first, refuse to ship work known to be unsafe."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating release day as the finish line and under-investing in maintenance and documentation. Mistake: taking on technical debt silently, so no one tracks it and it quietly grinds future work to a halt. Exit: (a) What does the ''CD'' in CI/CD refer to? (b) Give one professional ethical responsibility an engineer owes the public. Answers: (a) Continuous delivery, or deployment - automatically getting tested changes ready for, or into, production. (b) For example, protecting user data and privacy, being honest about risks, or refusing to ship unsafe work."}]}'::jsonb, 'Shipping is not the end; maintenance, honest documentation, and responsible conduct carry the real weight of a system''s life.', 14)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000036' and l.position = v.pos
);
